actions.script:
def q = ec.web.getRequest().getParameter("query")
def out = [response: null]
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def r = ec.service.sync().name("zenith.base.AiServices.ask#Copilot").parameter("query", q).call()
    out.response = r?.response ?: "Sorry, I couldn't generate a response."
} catch (Exception e) {
    out.response = "Sorry, the assistant is unavailable right now."
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
ec.web.sendJsonResponse(out)

def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
def result = [isSaasTenant:false, hasAllAccess:false, posOnly:false, isAdmin:false, modules:[]]
// ZE-SETTINGS-0203: expose admin status so the /qapps menu-filter hides Settings from non-admins.
result.isAdmin = ec.user.isInGroup("ZENITH_ADMIN") || ec.user.isInGroup("ADMIN")
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zr = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        result.posOnly = (_zr.size() == 1 && _zr.contains("ZENITH_CASHIER"))
    }
} catch (Exception e) {}
if (orgId) {
    boolean d = ec.artifactExecution.disableAuthz()
    try {
        def tl = ec.entity.find("zenith.erp.saas.SaasTenant")
            .condition("organizationPartyId", orgId)
            .condition("statusId", "SaasTenantActive").list()
        if (tl) {
            result.isSaasTenant = true
            def pm = ec.entity.find("zenith.erp.saas.SaasPlanModule")
                .condition("planId", tl[0].planId).list()
            def mods = pm.collect { it.moduleId.toLowerCase() }
            result.modules = mods
            result.hasAllAccess = mods.contains("all")
        }
    } catch (Exception e) {}
    finally { if (!d) ec.artifactExecution.enableAuthz() }
}
ec.web.sendJsonResponse(result)

pre-actions.script:
if (html_stylesheets == null) html_stylesheets = []
html_stylesheets.add('/zenithstatic/css/zenith-theme-v4.css?v=12')
html_stylesheets.add('https://fonts.googleapis.com/icon?family=Material+Icons')
if (footer_scripts == null) footer_scripts = []
footer_scripts.add('/zenithstatic/js/saas-menu-filter.js?v=11')
footer_scripts.add('/zenithstatic/js/zenith-copilot.js?v=5')
footer_scripts.add('/zenithstatic/js/pw-autofill-guard.js?v=2')

// SaaS tenant resolution: auto-set org from subdomain if not already set
def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
if (!orgId && ec.web) {
    try {
        def hostname = ec.web.getRequest()?.getServerName()
        if (hostname && hostname.contains('.') && !hostname.startsWith('localhost') && !hostname.startsWith('127.')) {
            boolean wasDisabled = ec.artifactExecution.disableAuthz()
            try {
                def tenantRec = ec.entity.find("zenith.erp.saas.SaasTenant")
                    .condition("subdomain", hostname.split('\\.')[0]).one()
                if (tenantRec && tenantRec.organizationPartyId) {
                    orgId = tenantRec.organizationPartyId
                    ec.user.setPreference("ACTIVE_ORGANIZATION", orgId)
                }
            } catch (Exception e) { /* SaasTenant entity may not exist yet */ }
            finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
        }
    } catch (Exception e) { /* ignore in non-web context */ }
}

// Load active company settings into screen context for all child screens
if (orgId) {
    boolean alreadyDisabled = ec.artifactExecution.disableAuthz()
    try {
        def settingsList = ec.entity.find("zenith.erp.base.CompanySettings")
                .condition("organizationPartyId", orgId).list()
        def getSetting = { String key -> settingsList?.find { it.settingKey == key }?.settingValue }

        context.activeOrgId = orgId
        context.companyCurrency = getSetting("CURRENCY_UOM_ID") ?: "INR"
        context.companyCountry = getSetting("COUNTRY_GEO_ID") ?: "IND"
        context.companyFyStartMonth = (getSetting("FY_START_MONTH") ?: "4") as int

        def currSymbols = [INR:"₹", USD:"\$", GBP:"£", AED:"AED ", EUR:"€", JPY:"¥"]
        context.currSymbol = currSymbols[context.companyCurrency] ?: (context.companyCurrency + " ")

        def cc = ec.entity.find("zenith.erp.base.CountryConfiguration")
                .condition("countryGeoId", context.companyCountry).one()
        context.companyNumberFormat = cc?.numberFormatPattern ?: "###,###.##"
        context.companyDateFormat = cc?.dateFormatPattern ?: "yyyy-MM-dd"

        // FY label for current date
        def now = java.time.LocalDate.now()
        int fyYear = now.monthValue >= context.companyFyStartMonth ? now.year : now.year - 1
        context.companyFyStart = fyYear
        context.companyFyLabel = (fyYear % 100).toString().padLeft(2, '0') + '-' + ((fyYear + 1) % 100).toString().padLeft(2, '0')
    } finally {
        if (!alreadyDisabled) ec.artifactExecution.enableAuthz()
    }
} else {
    context.activeOrgId = null
    context.companyCurrency = "INR"
    context.companyCountry = "IND"
    context.companyFyStartMonth = 4
    context.currSymbol = "₹"
    context.companyNumberFormat = "##,##,###.##"
    context.companyDateFormat = "dd/MM/yyyy"
    def now = java.time.LocalDate.now()
    context.companyFyStart = now.monthValue >= 4 ? now.year : now.year - 1
    context.companyFyLabel = (context.companyFyStart % 100).toString().padLeft(2, '0') + '-' + ((context.companyFyStart + 1) % 100).toString().padLeft(2, '0')
}

// SaaS module access gating: load allowed modules for tenant
context.isSuperAdmin = ec.user.isInGroup("ADMIN")
// ZE-SETTINGS-0203: only ZENITH_ADMIN/ADMIN may manage Settings. Expose it so the client
// menu-filter hides the Settings item from non-admins (they'd only hit "Access Restricted").
context.canManageSettings = ec.user.isInGroup("ZENITH_ADMIN") || ec.user.isInGroup("ADMIN")
context.isSaasTenant = false
context.isSaasSuspended = false
context.saasAllowedModules = null
context.saasPlanName = null
context.saasAllowedModulesJson = '[]'
if (orgId) {
    boolean gateDisabled = ec.artifactExecution.disableAuthz()
    try {
        // Check for active tenant
        def tenantList = ec.entity.find("zenith.erp.saas.SaasTenant")
            .condition("organizationPartyId", orgId)
            .condition("statusId", "SaasTenantActive").list()
        if (tenantList) {
            context.isSaasTenant = true
            def tenant = tenantList[0]
            def plan = ec.entity.find("zenith.erp.saas.SaasPlan")
                .condition("planId", tenant.planId).one()
            context.saasPlanName = plan?.planName ?: tenant.planId

            def planModules = ec.entity.find("zenith.erp.saas.SaasPlanModule")
                .condition("planId", tenant.planId).list()
            def moduleSet = new HashSet()
            planModules.each { moduleSet.add(it.moduleId.toLowerCase()) }
            context.saasAllowedModules = moduleSet
            context.saasHasAllAccess = moduleSet.contains("all")
            context.saasAllowedModulesJson = '[' + moduleSet.collect{ '"' + it + '"' }.join(',') + ']'
        } else {
            // Check if tenant exists but is suspended
            def suspendedList = ec.entity.find("zenith.erp.saas.SaasTenant")
                .condition("organizationPartyId", orgId)
                .condition("statusId", "SaasTenantSuspended").list()
            if (suspendedList) {
                context.isSaasTenant = true
                context.isSaasSuspended = true
                context.saasPlanName = suspendedList[0].planId
            }
        }
    } catch (Exception e) { /* SaaS entities may not exist */ }
    finally { if (!gateDisabled) ec.artifactExecution.enableAuthz() }
}

// ===== Role-based access: POS-only cashiers =====
// A user whose ONLY Zenith role is ZENITH_CASHIER (POS Cashier — POS Terminal Only) gets a
// POS-only experience: the nav menu is trimmed to POS (client) and every other module screen
// bounces to the terminal (server, below). Anyone with a broader role (admin/manager/etc.)
// or the platform super-admin is unaffected.
context.posOnlyUser = false
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zr = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        context.posOnlyUser = (_zr.size() == 1 && _zr.contains("ZENITH_CASHIER"))
    }
} catch (Exception e) { context.posOnlyUser = false }

// ===== Server-side module enforcement (plan gate + role gate; single reusable place) =====
// Modules must not be reachable by ANY route (direct URL, stale cached menu, etc.) - the
// client menu/tile filters are advisory only. Fail-OPEN: only redirect when the request path
// POSITIVELY names a known module the user may not reach. Platform super-admin (ADMIN) passes.
if (ec.web != null && !ec.user.isInGroup("ADMIN")) {
    def gateableModules = ['pos','sales','purchase','inventory','accounting','contacts','crm','hr',
        'payroll','attendance','timeoff','recruitment','expenses','manufacturing','quality','maintenance',
        'fleet','helpdesk','marketing','ecommerce','events','subscriptions','documents','approvals',
        'integrations','website','studio','plm','fieldservice','discuss','sign','project','timesheets',
        'tax','pricing','barcode'] as Set
    def reqMod = null
    def isAppRoot = false
    def isPosModuleRoot = false   // bare /apps/zenith/pos (the POS module now defaults to its Dashboard)
    try {
        def uri = ec.web.getRequest()?.getRequestURI()   // e.g. /apps/zenith/Accounting/AcctgDashboard
        if (uri) {
            def segs = uri.split('/').findAll { it }
            int zi = segs.findIndexOf { it.toLowerCase() == 'zenith' }
            if (zi >= 0) {
                if (zi + 1 < segs.size()) {
                    reqMod = segs[zi + 1].toLowerCase()
                    // 'pos' is the LAST segment -> the module root, which now lands on the POS
                    // Dashboard. A POS-only cashier must still go straight to the billing terminal.
                    if (reqMod == 'pos' && zi + 2 >= segs.size()) isPosModuleRoot = true
                }
                else isAppRoot = true   // bare /apps/zenith (renders the default Dashboard)
            }
        }
    } catch (Exception e) { reqMod = null }
    // PLAN gate: a plan-gated tenant must not reach a module screen its plan excludes.
    if (context.isSaasTenant && !context.saasHasAllAccess && context.saasAllowedModules != null
            && reqMod && gateableModules.contains(reqMod) && !context.saasAllowedModules.contains(reqMod)) {
        ec.message.addMessage("That module isn't included in your current plan.")
        def _shd = (ec.web.getRequest()?.getRequestURI() ?: '').startsWith('/qapps/') ? '/qapps' : '/apps'
        sri.sendRedirectAndStopRender(_shd + "/zenith/Dashboard")
    }
    // ROLE gate (general — ZE-ROLE-005 "No Access" enforcement): a non-admin user must not reach a
    // gateable module that NONE of their roles grants. Moqui's native ArtifactAuthz gates the nav
    // menu but NOT direct-URL screen renders, so removing a role's grant ("No Access") did not deny
    // by URL. Enforce it here. Module <mod> -> artifact group Z_<MOD>. Tenant admins (ZENITH_ADMIN)
    // see everything; POS-only cashiers are handled by the block below; any error / no-groups /
    // unmapped module FAILS OPEN so nobody is wrongly locked out (MARUTHI's users are all ZENITH_ADMIN
    // or ZENITH_CASHIER, so this gate is a no-op for them).
    if (reqMod && gateableModules.contains(reqMod) && !context.posOnlyUser
            && !ec.user.isInGroup("ZENITH_ADMIN")) {
        boolean roleGranted = true
        try {
            def _myG = (ec.user.userGroupIdSet ?: []) as List
            if (_myG) {
                boolean _dz = ec.artifactExecution.disableAuthz()
                try {
                    roleGranted = ec.entity.find("moqui.security.ArtifactAuthz")
                            .condition("artifactGroupId", "Z_" + reqMod.toUpperCase())
                            .condition("userGroupId", "in", _myG)
                            .condition("authzTypeEnumId", "in", ["AUTHZT_ALLOW", "AUTHZT_ALWAYS"])
                            .count() > 0
                } finally { if (!_dz) ec.artifactExecution.enableAuthz() }
            }
        } catch (Exception e) { roleGranted = true }   // fail OPEN — never lock a user out on error
        if (!roleGranted) {
            ec.message.addMessage("Your role doesn't include access to that module. Contact your administrator.")
            def _shr = (ec.web.getRequest()?.getRequestURI() ?: '').startsWith('/qapps/') ? '/qapps' : '/apps'
            sri.sendRedirectAndStopRender(_shr + "/zenith/Dashboard")
        }
    }
    // ROLE gate: a POS-only cashier is TILL-FIRST but may step out to the Dashboard and
    // Inventory (create/manage items) and back — every OTHER module still bounces to the
    // terminal (ZE-POS-0201: reporter wanted cashiers to reach the Dashboard + create items).
    // The app root still bounces to the terminal so LOGIN lands straight in the till (snappy —
    // the /apps optimistic cart; /qapps strips that JS so each tap round-trips over the
    // India<->Germany hop). The Dashboard is reached via its explicit /apps/zenith/Dashboard
    // link (not the app root). Inventory needs the ZENITH_CASHIER→Z_INVENTORY authz grant too.
    if (context.posOnlyUser && (isAppRoot || isPosModuleRoot
            || (reqMod && gateableModules.contains(reqMod) && reqMod != 'pos' && reqMod != 'inventory'))) {
        sri.sendRedirectAndStopRender("/apps/zenith/pos/Terminal")
    }
}

actions.script:
context.saasModuleBlocked = false
if (isSaasTenant && !saasHasAllAccess && saasAllowedModules != null) {
    def reqUri = ec.web?.getRequest()?.getRequestURI() ?: ''
    def parts = reqUri.split('/')
    def currentModule = (parts.length > 3) ? parts[3]?.toLowerCase() : null
    def alwaysAllowed = ['dashboard', 'settings', 'saas-admin', 'my-subscription', 'mypassword'] as Set
    if (currentModule && !alwaysAllowed.contains(currentModule) && !saasAllowedModules.contains(currentModule)) {
        context.saasModuleBlocked = true
        context.saasBlockedModule = currentModule
    }
}
